def get_command():
    cmd = Command(glom_cli, name='glom')

    cmd.add(Flag('--target-file', missing=None))
    cmd.add(Flag('--target-format', missing='json'))
    cmd.add(Flag('--spec-file', missing=None))
    cmd.add(Flag('--spec-format', missing='python'))
    cmd.add(Flag('--indent', parse_as=int, missing=2))
    cmd.add(Flag('--debug', parse_as=True, missing=False))
    cmd.add(Flag('--inspect', parse_as=True, missing=False))
    cmd.add(Flag('--scalar', parse_as=True, missing=False))
    cmd.add(PosArgSpec(display=PosArgDisplay(name='spec [target]', doc='glom spec and optional target data'), min_count=0, max_count=2))

    cmd.add(mw_get_target)
    cmd.add(mw_handle_target)

    return cmd

def main(argv):
    cmd = get_command()
    return cmd.run(argv)

def _from_glom_import_star():
    import glom as glom_mod
    env = {}
    for name in dir(glom_mod):
        if not name.startswith('_'):
            env[name] = getattr(glom_mod, name)
    return env

def _eval_python_full_spec(py_text):
    env = _from_glom_import_star()
    return _compile_code(py_text, '<spec>', env=env)

def _compile_code(code_str, name, env=None, verbose=False):
    if env is None:
        env = {}
    code = compile(code_str, name, 'eval')
    return eval(code, env)
